if(typeof globalThis.navIcon!=='function')globalThis.navIcon=function(id,f){return f};
const $=s=>document.querySelector(s);const navs=[['overview','◫','نظرة عامة'],['attendance','◷','الحضور والانصراف'],['staff','♙','فريق العمل'],['shifts','▦','الورديات'],['requests','▤','الطلبات والإجازات'],['payroll','▣','المرتبات والمستحقات'],['tasks','☑','المهام اليومية'],['permissions','⚙','الصلاحيات والفروع']];
const seed={staff:[{id:1,name:'أحمد محمود',job:'مدرب لياقة',branch:'الشباب — فودافون',time:'08:54',status:'حاضر',salary:8000},{id:2,name:'محمد عادل',job:'استقبال',branch:'الشباب — فودافون',time:'09:02',status:'متأخر',salary:6000},{id:3,name:'سارة أحمد',job:'مدربة لياقة',branch:'فرع السيدات',time:'08:47',status:'حاضر',salary:8000},{id:4,name:'كريم حسن',job:'مشرف صالة',branch:'الشباب — فودافون',time:'08:50',status:'حاضر',salary:7000},{id:5,name:'نور علي',job:'خدمة عملاء',branch:'فرع السيدات',time:'—',status:'إجازة',salary:5500},{id:6,name:'عمر إبراهيم',job:'صيانة',branch:'الشباب — فودافون',time:'—',status:'غائب',salary:6500}],requests:[{id:1,name:'محمد عادل',type:'إذن انصراف مبكر',detail:'ظرف عائلي • اليوم، ٣:٠٠ م',status:'معلق'},{id:2,name:'سارة أحمد',type:'إجازة اعتيادية',detail:'يوم واحد • ٢٠ أكتوبر',status:'معلق'},{id:3,name:'كريم حسن',type:'تصحيح بصمة',detail:'نسيان تسجيل الانصراف أمس',status:'معلق'}],tasks:[{id:1,title:'فحص أجهزة الكارديو قبل بداية الوردية',done:true},{id:2,title:'مراجعة نظافة الصالة وغرف تغيير الملابس',done:false},{id:3,title:'تسليم عهدة الاستقبال للوردية المسائية',done:false}],shifts:[{name:'الوردية الصباحية',time:'09:00 — 17:00',branch:'الشباب — فودافون'},{name:'الوردية المسائية',time:'17:00 — 01:00',branch:'الشباب — فودافون'},{name:'وردية السيدات',time:'09:00 — 17:00',branch:'فرع السيدات'}],checked:false,permissions:{},logs:[]};let db;try{db=JSON.parse(localStorage.getItem('energy-staff-v1'))||structuredClone(seed)}catch{db=structuredClone(seed)}let page='overview',role='الإدارة';function save(){localStorage.setItem('energy-staff-v1',JSON.stringify(db))}function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3200)}function list(){return db.staff.filter(s=>$('#branch').value==='كل الفروع'||s.branch===$('#branch').value)}function badge(s){return `<span class="badge ${s==='متأخر'||s==='معلق'?'amber':s==='غائب'||s==='إجازة'||s==='مرفوض'?'gray':''}">${esc(s)}</span>`}function card(title,body,action=''){return `<section class="card"><div class="card-head"><h2>${title}</h2>${action}</div>${body}</section>`}function table(rows,pay=false){return `<div class="table-wrap"><table><thead><tr><th>الموظف</th><th>الفرع</th><th>${pay?'الأساسي':'الحضور'}</th><th>${pay?'التقديري':'الحالة'}</th></tr></thead><tbody>${rows.map(s=>`<tr><td><div class="person"><span class="initial">${esc(s.name[0])}</span><div>${esc(s.name)}<small>${esc(s.job)}</small></div></div></td><td>${esc(s.branch)}</td><td>${pay?s.salary.toLocaleString()+' ج.م':s.time}</td><td>${pay?s.salary.toLocaleString()+' ج.م':badge(s.status)}</td></tr>`).join('')}</tbody></table></div>`}function requests(all=false){let rows=db.requests.filter(r=>all||r.status==='معلق');return rows.map(r=>`<div class="request"><div class="initial">${esc(r.name[0])}</div><div class="details"><strong>${esc(r.name)} <span style="color:#a2aaa4;font-weight:400">/ ${esc(r.type)}</span></strong><p>${esc(r.detail)}</p>${requestMeta(r)}</div>${r.status==='معلق'&&(role==='الإدارة'||role==='مدير قسم')?`<button data-approve="${r.id}">✓</button><button class="reject" data-reject="${r.id}">✕</button>`:badge(r.status)}</div>`).join('')||'<div class="empty">مفيش طلبات معلقة. كله تحت السيطرة ✓</div>'}function requestMeta(r){const bits=[];if(r.day)bits.push('اليوم: '+r.day);if(r.hours)bits.push(r.hours+' ساعة');if(r.status==='مقبول')bits.push(r.paid?'مدفوع':'غير مدفوع');if(r.status==='مرفوض'&&r.reviewNote)bits.push('سبب الرفض: '+r.reviewNote);if(r.reviewedBy)bits.push('راجعه: '+r.reviewedBy);return bits.length?`<p style="color:#a2aaa4;font-size:12px">${bits.map(esc).join(' • ')}</p>`:''}
function reviewRequest(id,approved){const r=db.requests.find(r=>r.id===Number(id));if(!r)return;const hoursField=approved?`<label>عدد الساعات المعتمدة<input name="hours" type="number" min="0.5" max="24" step="0.5" value="${r.hours||''}"></label>`:'';safeSubmit((approved?'قبول':'رفض')+' طلب '+r.name+' — '+r.type,(approved?options('الاحتساب','paid',['مدفوع','غير مدفوع']):'')+hoursField+(approved?'':field('سبب الرفض','note')),f=>{r.status=approved?'مقبول':'مرفوض';if(approved){r.paid=f.get('paid')==='مدفوع';if(f.get('hours'))r.hours=Number(f.get('hours'))}else{r.reviewNote=String(f.get('note')||'').slice(0,500)}r.reviewedBy=role==='الإدارة'?'الإدارة':'مدير قسم '+managerDepartment;r.reviewedAt=new Date().toISOString();db.logs.push(`${r.type} — ${r.name}: ${r.status}`);toast('تم تحديث حالة الطلب')})}
function stats(){let rows=list();return `<div class="stats">${[['إجمالي الموظفين',rows.length,navIcon('staff'),'فريق واحد، هدف واحد'],['الحاضرون الآن',rows.filter(s=>s.status==='حاضر'||s.status==='متأخر').length,navIcon('attendance'),'متابعة مباشرة لليوم التجريبي'],['متأخرون اليوم',rows.filter(s=>s.status==='متأخر').length,navIcon('alarm'),'مراجعة أسباب التأخير'],['طلبات تنتظر موافقتك',db.requests.filter(r=>r.status==='معلق').length,navIcon('requests'),'جاهزة للمراجعة']].map(([t,n,i,f])=>`<div class="stat"><div class="stat-top">${t}<span class="stat-icon">${i}</span></div><strong>${n.toString().padStart(2,'0')}</strong><small>${f}</small></div>`).join('')}</div>`}function render(){ $('#nav').innerHTML=navs.map(([id,i,t])=>`<button data-page="${id}" class="${page===id?'active':''}"><i>${navIcon(id,i)}</i>${t}${id==='requests'?`<em>${db.requests.filter(r=>r.status==='معلق').length}</em>`:''}</button>`).join('');$('#crumb').textContent=navs.find(n=>n[0]===page)[2];$('#title').textContent=page==='overview'?(role==='الإدارة'?'صباح الطاقة، كابتن مروان ✳':'أهلًا أحمد، جاهز ليوم جديد؟ ✳'):navs.find(n=>n[0]===page)[2];$('#add').textContent=role==='الموظف'?'＋ طلب جديد':'＋ إضافة موظف';let html='';if(role==='الموظف'){html=`<div class="notice">واجهة موظف تجريبية باسم أحمد محمود. التبديل بين الأدوار للمعاينة فقط.</div>${card('ورديتك النهارده',`<div class="employee-hero"><span>الشباب — فودافون • 09:00 إلى 17:00</span><strong>${new Date().toLocaleTimeString('ar-EG',{hour:'2-digit',minute:'2-digit'})}</strong><p>${db.checked?'تم تسجيل حضورك التجريبي':'سجّل بداية يومك وخليك جاهز'}</p><button class="primary" id="check">${db.checked?'تسجيل الانصراف التجريبي':'تسجيل حضور تجريبي'}</button><p>تسجيل تجريبي بدون التحقق من GPS</p></div>`)}<div class="grid">${card('مهامي اليومية',taskList())}${card('طلباتي',requests(true),'<button id="requestNew">＋ طلب جديد</button>')}</div>`}else if(page==='overview'){html=stats()+`<div class="grid"><div>${card('حركة الحضور هذا الأسبوع <small> / بيانات توضيحية</small>',`<div class="bars">${[70,84,65,91,80,95,76].map((h,i)=>`<div class="bar-group"><div class="bar dark" style="height:${h}%"></div><div class="bar" style="height:${h*.72}%"></div><small>${['السبت','الأحد','الإثنين','الثلاثاء','الأربعاء','الخميس','الجمعة'][i]}</small></div>`).join('')}</div><div class="chart-key"><b>●</b> الحضور <b style="color:#dfeadf">●</b> في الموعد</div>`,'<small>الأسبوع الحالي ▾</small>')}${card('فريقك النهارده',table(list()),'<button data-page="attendance">عرض الكل ←</button>')}</div><div><div class="welcome"><div class="tag">YOUR TEAM. YOUR ENERGY.</div><h2>فريق منظّم.<br>جيم في أفضل حالاته.</h2><p>تابع التفاصيل الصغيرة، وركّز على الصورة الكبيرة.</p><button data-page="shifts">راجع جدول الورديات ←</button></div>${card('طلبات تحتاج انتباهك',requests(),'<button data-page="requests">كل الطلبات ←</button>')}${card('آخر النشاطات',db.logs.slice(-3).reverse().map(x=>`<div class="activity"><i>●</i><p>${esc(x)}</p></div>`).join('')||'<div class="activity"><i>◷</i><div><p>أحمد محمود سجل حضوره</p><small>بيانات توضيحية • 08:54 ص</small></div></div><div class="activity"><i>✓</i><div><p>فحص أجهزة الكارديو مكتمل</p><small>بيانات توضيحية • 08:30 ص</small></div></div>')}</div></div>`}else if(page==='staff'||page==='attendance'){html=stats()+card(page==='staff'?'دليل فريق العمل':'سجل اليوم التجريبي',`<div class="toolbar"><input id="search" placeholder="ابحث باسم الموظف أو وظيفته…"><button id="export">↓ تصدير CSV</button></div><div id="rows">${table(list())}</div>`)}else if(page==='requests'){html=card('طلبات الفريق',requests(true),'<button id="requestNew">＋ إضافة طلب</button>')}else if(page==='shifts'){html=`<div class="notice">جدول ورديات تجريبي. الوردية المسائية تمتد لليوم التالي.</div>`+card('تخطيط الورديات',`<div class="table-wrap"><table><tr><th>الوردية</th><th>الوقت</th><th>الفرع</th></tr>${db.shifts.map(s=>`<tr><td>${esc(s.name)}</td><td dir="ltr">${esc(s.time)}</td><td>${esc(s.branch)}</td></tr>`).join('')}</table></div>`,'<button id="shiftNew">＋ وردية جديدة</button>')}else if(page==='payroll'){html=`<div class="notice">قيم تقديرية من الراتب الأساسي فقط؛ لم يتم احتساب خصومات أو إضافي، ولم يتم تسجيل أي صرف فعلي.</div>`+card('مسودة مستحقات الفريق',table(list(),true),'<button id="salaryEdit">تعديل راتب أساسي</button>')}else if(page==='tasks'){html=card('قائمة تشغيل الجيم',taskList(),'<button id="taskNew">＋ مهمة جديدة</button>')}else{html=`<div class="notice">إعدادات معاينة محلية. تطبيق الصلاحيات الآمن يحتاج تسجيل دخول وقاعدة بيانات وخادم.</div>`+card('صلاحيات مدير الفرع',`<div class="toolbar"><select id="permissionBranch"><option>الشباب — فودافون</option><option>فرع السيدات</option></select></div>${['رؤية موظفي الفرع','مراجعة الحضور والانصراف','قبول ورفض طلبات الحضور','إدارة الورديات','عرض المرتبات','تعديل الرواتب','إدارة الموظفين'].map((t,i)=>`<label class="task"><input type="checkbox" data-permission="${i}" ${db.permissions[i]?'checked':''}>${t}</label>`).join('')}<div class="toolbar"><button class="primary" id="savePermissions">حفظ إعدادات المعاينة</button></div>`)}$('#app').innerHTML=html;bind()}
function taskList(){return db.tasks.map(t=>`<label class="task ${t.done?'done':''}"><input type="checkbox" data-task="${t.id}" ${t.done?'checked':''}><span>${esc(t.title)}</span></label>`).join('')}function openForm(title,fields,submit){$('#modalTitle').textContent=title;$('#fields').innerHTML=fields;$('#form').onsubmit=e=>{e.preventDefault();submit(new FormData(e.target));save();$('#modal').close();render();toast('تم حفظ البيانات التجريبية')};$('#modal').showModal()}function field(t,n,type='text',value=''){return `<label>${t}<input name="${n}" type="${type}" value="${esc(value)}" required ${type==='number'?'min="0"':''}></label>`}function options(t,n,values){return `<label>${t}<select name="${n}">${values.map(v=>`<option>${esc(v)}</option>`).join('')}</select></label>`}function newRequest(){openForm('طلب جديد',options('الموظف','name',role==='الموظف'?['أحمد محمود']:db.staff.map(s=>s.name))+options('نوع الطلب','type',['إجازة اعتيادية','إجازة مرضية','إذن انصراف مبكر','إذن تأخير وصول','إذن خروج وعودة أثناء الوردية','تصحيح بصمة','تبديل وردية'])+field('التفاصيل والموعد','detail')+'<label>اليوم (اختياري)<input name="day" type="date"></label><label>عدد الساعات (اختياري)<input name="hours" type="number" min="0.5" max="24" step="0.5"></label>',f=>{const r={id:Date.now(),name:f.get('name'),type:f.get('type'),detail:f.get('detail'),status:'معلق'};if(f.get('day'))r.day=f.get('day');if(f.get('hours'))r.hours=Number(f.get('hours'));db.requests.push(r)})}function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render()});document.querySelectorAll('[data-approve],[data-reject]').forEach(b=>b.onclick=()=>reviewRequest(b.dataset.approve||b.dataset.reject,!!b.dataset.approve));document.querySelectorAll('[data-task]').forEach(c=>c.onchange=()=>{db.tasks.find(t=>t.id==c.dataset.task).done=c.checked;save();render()});if($('#search'))$('#search').oninput=e=>{$('#rows').innerHTML=table(list().filter(s=>(s.name+s.job).includes(e.target.value)))};if($('#requestNew'))$('#requestNew').onclick=newRequest;if($('#check'))$('#check').onclick=()=>{db.checked=!db.checked;db.logs.push(db.checked?'أحمد محمود سجل حضورًا تجريبيًا':'أحمد محمود سجل انصرافًا تجريبيًا');save();render();toast('تم التسجيل التجريبي')};if($('#shiftNew'))$('#shiftNew').onclick=()=>openForm('إضافة وردية',field('اسم الوردية','name')+field('موعد البداية والنهاية','time')+options('الفرع','branch',['الشباب — فودافون','فرع السيدات']),f=>db.shifts.push(Object.fromEntries(f)));if($('#taskNew'))$('#taskNew').onclick=()=>openForm('إضافة مهمة',field('وصف المهمة','title'),f=>db.tasks.push({id:Date.now(),title:f.get('title'),done:false}));if($('#salaryEdit'))$('#salaryEdit').onclick=()=>openForm('تعديل الراتب الأساسي',options('الموظف','name',db.staff.map(s=>s.name))+field('الراتب بالجنيه','salary','number'),f=>{db.staff.find(s=>s.name===f.get('name')).salary=Number(f.get('salary'))});if($('#savePermissions'))$('#savePermissions').onclick=()=>{document.querySelectorAll('[data-permission]').forEach(c=>db.permissions[c.dataset.permission]=c.checked);save();toast('تم حفظ إعدادات المعاينة')};if($('#export'))$('#export').onclick=()=>{const safe=v=>'"'+String(v).replace(/^[=+@-]/,' $&').replace(/"/g,'""')+'"';let csv='\ufeff'+[['الموظف','الوظيفة','الفرع','الحضور','الحالة'],...list().map(s=>[s.name,s.job,s.branch,s.time,s.status])].map(r=>r.map(safe).join(',')).join('\r\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='Energy-Staff-Attendance.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}}
$('#add').onclick=()=>{if(role==='الموظف')return newRequest();openForm('إضافة موظف',field('الاسم الكامل','name')+field('الوظيفة','job')+options('الفرع','branch',['الشباب — فودافون','فرع السيدات'])+field('الراتب الأساسي بالجنيه','salary','number'),f=>db.staff.push({id:Date.now(),...Object.fromEntries(f),salary:Number(f.get('salary')),time:'—',status:'غائب'}))};$('#role').onchange=e=>{role=e.target.value;render()};$('#branch').onchange=()=>render();$('#bell').onclick=()=>toast(`لديك ${db.requests.filter(r=>r.status==='معلق').length} طلبات معلقة للمراجعة`);render();
